-- Warning W_RETYPED_COLUMN: The column pickslip_booked.qty_booked is float8 in AMOS but VARCHAR2 in the DWH. Its values may look different.
-- Warning W_RETYPED_COLUMN: The column pickslip_booked.qty_canceled is float8 in AMOS but VARCHAR2 in the DWH. Its values may look different.

SELECT
    WORKSTEP_LINK.WORKSTEP_LINKNO_I AS "z_WORKSTEP_LINK_ID",
    PART_REQUEST_2.PARTNO AS "z_PART_NO",
    PART_REQUEST_2.QTY AS "z_PART_QTY",
    PART_REQUEST_2.NO_PCF AS "z_PART_NO_PCF",
    PART.TOOL,
    PART_REQUEST_INFO.SERIALNO,
    PICKSLIP_DETAIL.PICKSLIPNO,
    PICKSLIP_BOOKED.QTY_BOOKED,
    PICKSLIP_BOOKED.QTY_CANCELED,
    PICKSLIP_BOOKED.BATCHNO,
    PICKSLIP_BOOKED.EXPIRE_DATE
FROM STG_AMOS.PART_REQUEST_2
JOIN STG_AMOS.WORKSTEP_LINK
    ON (WORKSTEP_LINK.WORKSTEP_LINKNO_I = PART_REQUEST_2.EVENT_KEY)
LEFT JOIN STG_AMOS.PART
    ON (PART.PARTNO = PART_REQUEST_2.PARTNO)
LEFT JOIN STG_AMOS.PART_REQUEST_INFO
    ON (PART_REQUEST_INFO.PART_REQUESTNO_I = PART_REQUEST_2.PART_REQUESTNO_I)
LEFT JOIN STG_AMOS.PICKSLIP_DETAIL
    ON (PICKSLIP_DETAIL.PART_REQUESTNO_I = PART_REQUEST_2.PART_REQUESTNO_I)
LEFT JOIN STG_AMOS.PICKSLIP_BOOKED
    ON ((PICKSLIP_BOOKED.PICKSLIPNO = PICKSLIP_DETAIL.PICKSLIPNO)
        AND (PICKSLIP_BOOKED.RECNO = PICKSLIP_DETAIL.RECNO))
WHERE ((PART_REQUEST_2.EVENT_TYPE = 'WSL')
    AND EXISTS (SELECT 1 FROM STG_AMOS.WP_HEADER JOIN STG_AMOS.WP_ASSIGNMENT ON (WP_ASSIGNMENT.WPNO_I = WP_HEADER.WPNO_I) JOIN STG_AMOS.WO_HEADER ON (WO_HEADER.EVENT_PERFNO_I = WP_ASSIGNMENT.EVENT_PERFNO_I) WHERE ((WO_HEADER.EVENT_PERFNO_I = WORKSTEP_LINK.EVENT_PERFNO_I) AND (WP_HEADER.WPNO = '<WP_NAME>'))))
